        offs = start + tl.arange(0, BLOCK)
        mask = offs < N
        a = tl.load(a_ptr + offs, mask=mask, other=0)
        b = tl.load(b_ptr + offs, mask=mask, other=0)
        if UPCAST:
            a = a.to(tl.float32)
            b = b.to(tl.float32)
        logy = tl.log(b)
        prod = a * logy
        zero = tl.zeros_like(prod)
        res = tl.where(a == 0, zero, prod)
        y_is_nan = b != b
        nan = tl.full(res.shape, float("nan"), res.dtype)
        res = tl.where(y_is_nan, nan, res)
        tl.store(out_ptr + offs, res, mask=mask)


