    bshape = torch.broadcast_shapes(A.shape, B.shape)
    out = torch.empty(bshape, dtype=out_dtype, device=A.device)
    N = out.numel()
    if N == 0:
        return out
    # Fast path: identical shapes, both contiguous. Use a larger tile here;
    # the flat kernel has no int64 index arithmetic so it tolerates BLOCK=6144,
    # cutting grid-stride iterations on the large (1B-element) workloads.
    if A.shape == B.shape == tuple(bshape) and A.is_contiguous() and B.is_contiguous():
        if N <= 8192:
            # Tiny workloads: a single small-tile program minimizes per-program
            # setup/launch overhead that the big persistent grid would add.
            SMALL_BLOCK = triton.next_power_of_2(N)
            _xlogy_flat_kernel[(1,)](
                A.reshape(-1), B.reshape(-1), out.reshape(-1), N, BLOCK=SMALL_BLOCK
            )
            return out
        # 2-byte inputs (fp16/bf16) leave more Unified Buffer headroom than
        # fp32, so a larger tile fits and cuts grid-stride iterations further.
        if A.element_size() <= 2:
            FLAT_BLOCK = 8192
        else:
            FLAT_BLOCK = 6144
        grid = _grid_for(N, FLAT_BLOCK)
        # Native-precision compute (no fp32 upcast) when inputs and output share
        # the same reduced-precision dtype: halves vector-register/UB pressure
        # and the log is done in-dtype. Correctness is gated by eval.
        upcast = not (A.dtype == B.dtype == out_dtype and A.element_size() <= 2)
        _xlogy_flat_kernel[grid](
            A.reshape(-1),
            B.reshape(-1),
            out.reshape(-1),
            N,
            BLOCK=FLAT_BLOCK,
            UPCAST=upcast,
        )
        return out

    # General strided broadcast path: keep the proven BLOCK=2048.
    BLOCK = 2048
    grid = _grid_for(N, BLOCK)
    rank = len(bshape)
    Ae = A.expand(bshape)
    Be = B.expand(bshape)
    shape_t = torch.tensor(list(bshape), dtype=torch.int64, device=A.device)
    out_stride_t = torch.tensor(list(out.stride()), dtype=torch.int64, device=A.device)
    a_stride_t = torch.tensor(list(Ae.stride()), dtype=torch.int64, device=A.device)
    b_stride_t = torch.tensor(list(Be.stride()), dtype=torch.int64, device=A.device)
    _xlogy_strided_kernel[grid](
        A,
        B,
        out.reshape(-1),
        N,
        shape_t,
        out_stride_t,
        a_stride_t,
        b_stride_t,
        RANK=rank,
        BLOCK=BLOCK,
    )
    return out
